1	// Reference solution — Exercise 04 Part B: lock-free SPSC ring buffer.
2	//
3	// Single-producer / single-consumer queue with release/acquire ordering and
4	// cache-line padding, per lessons 0009/0010. Usable capacity is N - 1 (one
5	// slot stays empty to distinguish full from empty).
6	//
7	// Peek policy: attempt exercises/04_spsc_ring/spsc_ring.hpp first.
8	#pragma once
9	
10	#include <array>
11	#include <atomic>
12	#include <cstddef>
13	
14	template <typename T, std::size_t N>
15	class SpscRing {
16	    static_assert(N >= 2 && (N & (N - 1)) == 0, "N must be a power of two");
17	
18	public:
19	    // Producer side only. Returns false when the ring is full.
20	    bool try_push(const T& v) noexcept {
21	        const std::size_t head = head_.load(std::memory_order_relaxed);
22	        const std::size_t next = (head + 1) & (N - 1);
23	        if (next == tail_.load(std::memory_order_acquire)) {
24	            return false;  // full
25	        }
26	        buf_[head] = v;
27	        // release: the consumer's acquire-load of head_ makes the write to
28	        // buf_[head] visible before it reads the slot.
29	        head_.store(next, std::memory_order_release);
30	        return true;
31	    }
32	
33	    // Consumer side only. Returns false when the ring is empty.
34	    bool try_pop(T& out) noexcept {
35	        const std::size_t tail = tail_.load(std::memory_order_relaxed);
36	        if (tail == head_.load(std::memory_order_acquire)) {
37	            return false;  // empty
38	        }
39	        out = buf_[tail];
40	        tail_.store((tail + 1) & (N - 1), std::memory_order_release);
41	        return true;
42	    }
43	
44	    static constexpr std::size_t capacity() noexcept { return N - 1; }
45	
46	private:
47	    std::array<T, N> buf_{};
48	    // Separate cache lines so producer (head_) and consumer (tail_) cores
49	    // don't false-share.
50	    alignas(64) std::atomic<std::size_t> head_{0};
51	    alignas(64) std::atomic<std::size_t> tail_{0};
52	};
