1	// Reference solution — Exercise 04 Part A: O(1) ring-buffer moving average.
2	//
3	// Fixes the O(window) recompute that gradient_boosting/
4	// sample_with_gradient_boosting.cpp admits it should avoid: a running sum
5	// over a fixed array gives O(1) push and O(1) average, no heap, no loop.
6	//
7	// Peek policy: attempt exercises/04_spsc_ring/ring_ma.hpp first.
8	#pragma once
9	
10	#include <array>
11	#include <cstddef>
12	
13	template <std::size_t N>
14	class RingMA {
15	    static_assert(N > 0, "window must be non-empty");
16	
17	public:
18	    // O(1): subtract the value falling out of the window, add the new one.
19	    void push(double x) noexcept {
20	        if (count_ == N) {
21	            sum_ -= buf_[head_];  // head_ points at the oldest sample
22	        } else {
23	            ++count_;
24	        }
25	        buf_[head_] = x;
26	        sum_ += x;
27	        head_ = (head_ + 1) % N;
28	    }
29	
30	    // Mean of the samples currently in the window (0.0 before any push).
31	    double average() const noexcept {
32	        return count_ == 0 ? 0.0 : sum_ / static_cast<double>(count_);
33	    }
34	
35	    std::size_t size() const noexcept { return count_; }
36	
37	    bool warmed_up() const noexcept { return count_ == N; }
38	
39	private:
40	    std::array<double, N> buf_{};  // fixed storage — no heap on the hot path
41	    double sum_ = 0.0;
42	    std::size_t head_ = 0;   // next write slot == oldest sample once full
43	    std::size_t count_ = 0;
44	};
