26	int test_single_thread_fifo() {
27	    SpscRing<int, 8> ring;
28	    ASSERT(ring.try_push(1), "push into empty ring should succeed");
29	    ASSERT(ring.try_push(2), "second push should succeed");
30	    ASSERT(ring.try_push(3), "third push should succeed");
31	    int v = 0;
32	    ASSERT(ring.try_pop(v) && v == 1, "first pop should yield 1");
33	    ASSERT(ring.try_pop(v) && v == 2, "second pop should yield 2");
34	    ASSERT(ring.try_pop(v) && v == 3, "third pop should yield 3");
35	    return 0;
36	}
