38	int test_empty_and_full_detection() {
39	    SpscRing<int, 8> ring;  // usable capacity 7
40	    int v = 0;
41	    ASSERT(!ring.try_pop(v), "pop from empty ring should fail");
42	    for (int i = 0; i < 7; ++i) {
43	        ASSERT(ring.try_push(i), "push " + std::to_string(i) + " should fit");
44	    }
45	    ASSERT(!ring.try_push(99), "8th push must fail: capacity is N-1");
46	    ASSERT(ring.try_pop(v) && v == 0, "pop should free a slot");
47	    ASSERT(ring.try_push(99), "push should succeed after a pop");
48	    return 0;
49	}
