51	int test_cache_line_padding() {
52	    // With alignas(64) on head_ and tail_, the object must span at least
53	    // buf (64B for 8 x uint64) + 64 + 64 = 192 bytes. Without the padding
54	    // it would be ~80 bytes — this catches a forgotten alignas.
55	    ASSERT(sizeof(SpscRing<std::uint64_t, 8>) >= 192,
56	           "head_/tail_ must each sit on their own 64-byte cache line "
57	           "(alignas(64)); sizeof = " + std::to_string(sizeof(SpscRing<std::uint64_t, 8>)));
58	    return 0;
59	}
