61	int test_two_thread_transfer() {
62	    constexpr std::uint64_t COUNT = 1'000'000;
63	    SpscRing<std::uint64_t, 1024> ring;
64	    std::atomic<bool> not_implemented{false};
65	    std::atomic<bool> stop{false};  // unblocks the producer's spin on any failure
66	    std::atomic<bool> order_ok{true};
67	    std::atomic<std::uint64_t> received{0};
68	
69	    std::thread producer([&] {
70	        try {
71	            for (std::uint64_t i = 0; i < COUNT; ++i) {
72	                while (!ring.try_push(i)) {
73	                    if (stop.load(std::memory_order_relaxed)) return;
74	                }
75	            }
76	        } catch (const std::logic_error&) {
77	            not_implemented.store(true);
78	            stop.store(true);
79	        }
80	    });
81	
82	    std::thread consumer([&] {
83	        try {
84	            std::uint64_t expect = 0;
85	            std::uint64_t v = 0;
86	            while (expect < COUNT && !stop.load(std::memory_order_relaxed)) {
87	                if (ring.try_pop(v)) {
88	                    if (v != expect) {
89	                        order_ok.store(false);
90	                        stop.store(true);
91	                        break;
92	                    }
93	                    ++expect;
94	                }
95	            }
96	            received.store(expect);
97	        } catch (const std::logic_error&) {
98	            not_implemented.store(true);
99	            stop.store(true);
100	        }
101	    });
102	
103	    producer.join();
104	    consumer.join();
105	
106	    if (not_implemented.load()) throw std::logic_error("not implemented");
107	    ASSERT(order_ok.load(), "items arrived out of order or corrupted");
108	    ASSERT(received.load() == COUNT,
109	           "consumer received " + std::to_string(received.load())
110	           + " of " + std::to_string(COUNT));
111	    return 0;
112	}
113	
114	int main() {
115	    struct Test {
116	        const char* name;
117	        int (*fn)();
118	    };
119	    Test tests[] = {
120	        {"single_thread_fifo",       test_single_thread_fifo},
121	        {"empty_and_full_detection", test_empty_and_full_detection},
122	        {"cache_line_padding",       test_cache_line_padding},
123	        {"two_thread_transfer",      test_two_thread_transfer},
124	    };
125	
126	    try {
127	        int failed = 0;
128	        for (auto& t : tests) {
129	            if (t.fn() != 0) {
130	                std::cerr << "  [FAILED] " << t.name << "\n";
131	                ++failed;
132	            } else {
133	                std::cout << "  [PASSED] " << t.name << "\n";
134	            }
135	        }
