139	        }
140	        std::cerr << failed << " TEST(S) FAILED\n";
141	        return 1;
142	    } catch (const std::logic_error& e) {
143	        std::cout << "NOT IMPLEMENTED: " << e.what() << "\n";
144	        return 42;
145	    }
146	}
