25	int test_empty_average_is_zero() {
26	    RingMA<4> ma;
27	    ASSERT(ma.size() == 0, "fresh window should be empty");
28	    ASSERT(!ma.warmed_up(), "fresh window should not be warmed up");
29	    ASSERT(std::fabs(ma.average() - 0.0) < 1e-12,
30	           "average of empty window should be 0.0");
31	    return 0;
32	}
