34	int test_partial_window_average() {
35	    RingMA<4> ma;
36	    ma.push(2.0);
37	    ma.push(4.0);
38	    ASSERT(ma.size() == 2, "size should be 2 after two pushes");
39	    ASSERT(!ma.warmed_up(), "not warmed up before N samples");
40	    ASSERT(std::fabs(ma.average() - 3.0) < 1e-12,
41	           "average of {2,4} should be 3.0, got " + std::to_string(ma.average()));
42	    return 0;
43	}
