45	int test_warmup_flag() {
46	    RingMA<3> ma;
47	    ma.push(1.0);
48	    ma.push(1.0);
49	    ma.push(1.0);
50	    ASSERT(ma.warmed_up(), "warmed up after exactly N samples");
51	    ASSERT(ma.size() == 3, "size saturates at N");
52	    ma.push(1.0);
53	    ASSERT(ma.size() == 3, "size stays at N after wraparound");
54	    return 0;
