57	int test_matches_naive_across_wraparound() {
58	    constexpr std::size_t W = 5;
59	    RingMA<W> ma;
60	    std::deque<double> naive;
61	
62	    // Deterministic pseudo-random-ish sequence, long enough to wrap many times
63	    double x = 100.0;
64	    for (int i = 0; i < 200; ++i) {
65	        x += ((i * 37) % 11) - 5;  // jiggle
66	        ma.push(x);
67	        naive.push_back(x);
68	        if (naive.size() > W) naive.pop_front();
69	
70	        double expect = 0.0;
71	        for (double v : naive) expect += v;
72	        expect /= static_cast<double>(naive.size());
73	
74	        ASSERT(std::fabs(ma.average() - expect) < 1e-9,
75	               "average diverged from naive recompute at i=" + std::to_string(i)
76	               + ": got " + std::to_string(ma.average())
77	               + ", expected " + std::to_string(expect));
78	    }
79	    return 0;
80	}
